57|   availability(session: Session): Availability {
58|     const active = this.bookings
59|       .findBySession(session.id)
60|       .filter((b) => b.status === "pending" || b.status === "paid");
61|     const ticketsUsed = active.reduce((n, b) => n + b.tickets, 0);
62|     const hireLeft: Record<string, number> = {};
63|     for (const [size, total] of Object.entries(this.stock.all())) {
64|       const used = active.reduce((n, b) => n + (b.hire[size] ?? 0), 0);
65|       hireLeft[size] = total - used;
66|     }
67|     const capacity = this.effectiveCapacity(session);
68|     const selling = session.status === "open";
69|     return { capacity, ticketsLeft: selling ? Math.max(0, capacity - ticketsUsed) : 0, hireLeft };
